/* Glass — dark gradient bg, frosted blurred surfaces, thin light borders, glows */
.theme-glass {
  --bg: oklch(0.18 0.05 275);
  --surface: oklch(1 0 0 / 8%);
  --surface-2: oklch(1 0 0 / 14%);
  --fg: oklch(0.98 0.01 280);
  --fg-muted: oklch(0.84 0.03 280);
  --accent: oklch(0.78 0.16 195);
  --accent-fg: oklch(0.16 0.05 275);
  --accent-2: oklch(0.7 0.19 320);
  --line: oklch(1 0 0 / 20%);
  --success: oklch(0.78 0.16 160);
  --warning: oklch(0.84 0.16 85);
  --danger: oklch(0.7 0.2 15);

  --radius: 1.25rem;
  --radius-sm: 0.75rem;
  --radius-lg: 1.75rem;
  --radius-pill: 9999px;

  --shadow-1: 0 4px 20px -6px oklch(0 0 0 / 45%);
  --shadow-2: 0 16px 48px -12px oklch(0 0 0 / 55%);
  --shadow-3: 0 28px 80px -20px oklch(0 0 0 / 65%);
  --glow: 0 0 40px -6px color-mix(in oklab, var(--accent) 55%, transparent);

  --border-width: 1px;
  --blur-amount: 20px;

  --font-display: "Space Grotesk", "Inter", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.02em;
  --label-transform: none;
  --label-tracking: 0.02em;

  background-color: var(--bg);
  background-image:
    radial-gradient(60rem 40rem at 12% -10%, oklch(0.62 0.2 320 / 45%), transparent 60%),
    radial-gradient(50rem 36rem at 92% 8%, oklch(0.7 0.17 195 / 40%), transparent 60%),
    radial-gradient(70rem 50rem at 50% 110%, oklch(0.5 0.19 265 / 45%), transparent 65%);
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-glass h1,
.theme-glass h2,
.theme-glass h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-glass h1 { background: linear-gradient(100deg, var(--fg), var(--accent-2)); -webkit-background-clip: text; background-clip: text; color: transparent; }
.theme-glass button:hover { box-shadow: 0 0 24px color-mix(in oklab, var(--accent) 45%, transparent); }

/* depth */
.theme-glass thead th { background: oklch(1 0 0 / 6%); color: var(--fg-muted); font-family: var(--font-display); font-size: 0.72em; text-transform: uppercase; letter-spacing: 0.08em; border-bottom: 1px solid var(--line); }
.theme-glass td { border-bottom: 1px solid oklch(1 0 0 / 8%); }
.theme-glass tbody tr:hover { background: oklch(1 0 0 / 5%); }
.theme-glass input, .theme-glass textarea, .theme-glass select { background: oklch(1 0 0 / 7%); border: 1px solid var(--line); color: var(--fg); backdrop-filter: blur(12px); }
.theme-glass input::placeholder, .theme-glass textarea::placeholder { color: oklch(0.84 0.03 280 / 55%); }
.theme-glass input:focus-visible, .theme-glass textarea:focus-visible, .theme-glass select:focus-visible { outline: none; border-color: color-mix(in oklab, var(--accent) 70%, transparent); box-shadow: var(--glow); }
.theme-glass kbd { background: oklch(1 0 0 / 12%); border: 1px solid oklch(1 0 0 / 28%); border-top-color: oklch(1 0 0 / 55%); border-radius: 0.4em; padding: 0.1em 0.45em; font-family: var(--font-mono); font-size: 0.85em; }
.theme-glass a { color: var(--accent); text-decoration: underline; text-decoration-color: color-mix(in oklab, var(--accent) 40%, transparent); text-underline-offset: 0.2em; }
.theme-glass a:hover { text-decoration-color: var(--accent); text-shadow: 0 0 14px color-mix(in oklab, var(--accent) 60%, transparent); }
.theme-glass ::selection { background: color-mix(in oklab, var(--accent-2) 45%, transparent); color: var(--fg); }
.theme-glass ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-glass ::-webkit-scrollbar-track { background: oklch(1 0 0 / 4%); }
.theme-glass ::-webkit-scrollbar-thumb { background: oklch(1 0 0 / 22%); border-radius: 9999px; border: 2px solid transparent; background-clip: padding-box; }
.theme-glass ::-webkit-scrollbar-thumb:hover { background: color-mix(in oklab, var(--accent) 55%, oklch(1 0 0 / 25%)); border: 2px solid transparent; background-clip: padding-box; }
.theme-glass .label-caps { color: var(--accent); letter-spacing: 0.1em; }
.theme-glass .themed-border { border-color: var(--line); border-top-color: oklch(1 0 0 / 45%); }
.theme-glass button:active { transform: translateY(1px); box-shadow: 0 0 12px color-mix(in oklab, var(--accent) 30%, transparent); }

/* alt mode: frosted daylight — glass panes over a bright prism room */
.theme-glass.alt-mode {
  --bg: oklch(0.96 0.02 275);
  --surface: oklch(1 0 0 / 55%);
  --surface-2: oklch(1 0 0 / 75%);
  --fg: oklch(0.22 0.03 275);
  --fg-muted: oklch(0.44 0.03 275);
  --accent: oklch(0.52 0.14 195);
  --accent-fg: oklch(0.98 0.01 195);
  --line: oklch(0.4 0.04 275 / 22%);
  --shadow-1: 0 1px 3px oklch(0.3 0.05 275 / 12%);
  --shadow-2: 0 10px 28px -10px oklch(0.3 0.05 275 / 20%);
  --shadow-3: 0 24px 60px -18px oklch(0.3 0.05 275 / 28%);
  --glow: 0 0 32px -6px color-mix(in oklab, var(--accent) 45%, transparent);
  background-image:
    radial-gradient(60rem 40rem at 12% -10%, oklch(0.88 0.09 320 / 55%), transparent 60%),
    radial-gradient(50rem 36rem at 92% 8%, oklch(0.9 0.08 195 / 50%), transparent 60%);
}
.theme-glass.alt-mode input::placeholder, .theme-glass.alt-mode textarea::placeholder { color: oklch(0.44 0.03 275 / 65%); }
.theme-glass.alt-mode kbd { background: oklch(0.3 0.03 275 / 8%); border-color: oklch(0.3 0.03 275 / 22%); border-top-color: oklch(1 0 0 / 85%); }
.theme-glass.alt-mode thead th { background: oklch(0.3 0.03 275 / 5%); }
.theme-glass.alt-mode td { border-bottom-color: oklch(0.3 0.03 275 / 10%); }
.theme-glass.alt-mode tbody tr:hover { background: oklch(0.3 0.03 275 / 5%); }
.theme-glass.alt-mode ::-webkit-scrollbar-track { background: oklch(0.3 0.03 275 / 6%); }
.theme-glass.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.3 0.03 275 / 25%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
